(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.015+t*0.15)*8+Math.cos((y+w1y)*0.02-t*0.1)*6;
  const w2y = Math.cos((y+w1y)*0.015-t*0.2)*8+Math.sin((x+w1x)*0.012+t*0.25)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65)*40,0.14,1.3],
    [400+Math.cos(t*0.55+2)*70,200+Math.sin(t*0.75+1)*50,0.05,2.8],
    [200+Math.sin(t*0.7)*50,220+Math.cos(t*0.5+4)*60,0.11,1.6]
  ];
  let aS=0,iS=0,hrm=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hrm+=Math.sin(d*f*0.5-t*sp*0.3+2.1);
  }
  const n=src.length,act=aS/n,inh=iS/n,h=hrm/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+t*0.5)*Math.sin(sy*0.06-t*0.4)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.03-ang*6+t*0.8)*0.15;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const rd=Math.tanh((act-inh*0.7+bg*0.3+spiral+h*0.2)*2.2);
  const feedback=Math.sin(rd*Math.PI*2+h*Math.PI)*0.15;
  const reaction=Math.tanh((rd+feedback)*1.8);
  const detail=Math.sin(sx*0.3+sy*0.2+t*3)*Math.sin(sx*0.2-sy*0.3-t*2.5)*0.08;
  const blend=reaction*0.7+cell*0.2+detail*0.1,v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,85],[18,90,115],[25,140,130],[60,170,120],[140,190,80],[200,185,60],[215,150,65],[200,110,60],[170,65,60],[130,40,70],[85,25,65],[50,18,60],[20,14,55],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,reaction)*0.08;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*255)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*200)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*150)|0)
  ];
}
